(6, 6, 'Cours : Chapitre 1 - Ondes sur une corde vibrante', 'cours-tome-1-ondes-mecaniques-ch1-ondes-sur-une-corde-vibrante', 'Équation d\'Alembert, ondes progressives, réflexions aux limites, modes propres et énergie vibratoire.', NULL, '/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_1_Ondes_sur_une_corde_vibrante.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(7, 7, 'Cours : Chapitre 2 - Ondes acoustiques dans un fluide', 'cours-tome-1-ondes-mecaniques-ch2-ondes-acoustiques-dans-un-fluide', 'Propagation acoustique, équations d\'état des fluides, impédance acoustique, énergie et effet Doppler.', NULL, '/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_2_Ondes_acoustiques_dans_un_fluide.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(8, 8, 'Cours : Chapitre 3 - Autres types d\'ondes 1D (Barres, Câbles, Réseaux)', 'cours-tome-1-ondes-mecaniques-ch3-autres-types-d-ondes-1d', 'Ondes longitudinales dans les barres, milieux dispersifs, vitesse de phase et vitesse de groupe.', NULL, '/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_3_Autres_types_d_ondes_1D.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(9, 9, 'Cours : Chapitre 4 - Ondes de gravitation dans un liquide (Houle, Vagues)', 'cours-tome-1-ondes-mecaniques-ch4-ondes-de-gravitation-liquide', 'Théorie de la houle, équation d\'onde en eau profonde et peu profonde, dispersion et solitons.', NULL, '/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_4_Ondes_de_gravitation_liquide.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(10, 10, 'Cours : Chapitre 5 - Diffusion thermique et de particules', 'cours-tome-1-ondes-mecaniques-ch5-diffusion-thermique-et-particules', 'Loi de Fick, équation de la chaleur, régimes stationnaires et sinusoïdaux, marche au hasard.', NULL, '/assets/downloads/garing_decoupe/Tome_1_Ondes_Mecaniques/Chapitres/Chapitre_5_Diffusion_Thermique_et_Particules.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(11, 11, 'Cours : Chapitre 1 - Ondes Électromagnétiques dans le vide (OPPM)', 'cours-tome-2-ondes-em-vide-milieux-ch1-oem-dans-le-vide', 'Équations de Maxwell dans le vide, onde plane progressive harmonique, polarisation, vecteur de Poynting et pression de radiation.', NULL, '/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_1_OEM_dans_le_vide.pdf', 'l2', 1, '2026-08-13 22:53:55'),
(12, 12, 'Cours : Chapitre 2 - Lignes de transmission', 'cours-tome-2-ondes-em-vide-milieux-ch2-lignes-de-transmission', 'Équations des télégraphistes, impédance caractéristique, réflexions et régime sinusoïdal sur ligne.', NULL, '/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_2_Lignes_de_transmission.pdf', 'l2', 1, '2026-08-13 22:53:56'),
(13, 13, 'Cours : Chapitre 3 - Conducteurs métalliques et guides d\'ondes', 'cours-tome-2-ondes-em-vide-milieux-ch3-conducteurs-metalliques', 'Effet de peau, réflexion sur un conducteur parfait ou réel, propagation guidée et cavités résonantes.', NULL, '/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_3_Conducteurs_metalliques.pdf', 'l2', 1, '2026-08-13 22:53:56'),
(14, 14, 'Cours : Chapitre 4 - Ondes électromagnétiques dans un plasma', 'cours-tome-2-ondes-em-vide-milieux-ch4-ondes-dans-un-plasma', 'Modèle d\'Drude-Lorentz, fréquence plasma, propagation et réflexion ionosphérique.', NULL, '/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_4_Ondes_dans_un_plasma.pdf', 'l2', 1, '2026-08-13 22:53:56'),
(15, 15, 'Cours : Chapitre 5 - Rayonnement dipolaire et diffusion', 'cours-tome-2-ondes-em-vide-milieux-ch5-rayonnement-dipolaire-diffusion', 'Potentiels retardés, dipôle oscillant de Hertz, puissance rayonnée et diffusion Rayleigh / Thomson.', NULL, '/assets/downloads/garing_decoupe/Tome_2_Ondes_EM_Vide_et_Milieux/Chapitres/Chapitre_5_Rayonnement_dipolaire_diffusion.pdf', 'l2', 1, '2026-08-13 22:53:56'),
(16, 16, 'Cours : Chapitre 1 - Introduction aux milieux diélectriques', 'cours-tome-3-ondes-em-dielectriques-ch1-introduction-dielectriques', 'Polarisation de la matière, vecteur déplacement électrique D, polarisabilité moléculaire et condensateurs.', NULL, '/assets/downloads/garing_decoupe/Tome_3_Ondes_EM_Dielectriques/Chapitres/Chapitre_1_Introduction_Dielectriques.pdf', 'l3', 1, '2026-08-13 22:53:56'),
